<?php
namespace App\Http\Controllers;
use App\Models\{User,Department,ShiftType,RosterPeriod,ShiftPreference,RosterAssignment};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rule;
use Carbon\Carbon;
class RosterController extends Controller {
private function admin(){abort_unless(auth()->user()->role==='admin',403);}
private function period(Request $r){$month=$r->query('month',now()->format('Y-m'));abort_unless(preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month),422);return RosterPeriod::firstOrCreate(['month'=>$month.'-01']);}
private function data(RosterPeriod $period){$start=Carbon::parse($period->month);$days=range(1,$start->daysInMonth);$shifts=ShiftType::orderBy('id')->get();return compact('period','days','shifts');}
public function adminIndex(Request $r){$this->admin();$period=$this->period($r);$data=$this->data($period);$data['users']=User::where('role','nurse')->with('department')->orderBy('name')->get();$data['preferences']=ShiftPreference::where('period_id',$period->id)->get()->keyBy(fn($x)=>$x->user_id.'|'.$x->work_date);$data['assignments']=RosterAssignment::where('period_id',$period->id)->get()->keyBy(fn($x)=>$x->user_id.'|'.$x->work_date);$data['departments']=Department::all();return view('admin.index',$data);}
public function nurseIndex(Request $r){abort_unless(auth()->user()->role==='nurse',403);$period=$this->period($r);$data=$this->data($period);$data['preferences']=ShiftPreference::where('period_id',$period->id)->where('user_id',auth()->id())->get()->keyBy('work_date');$data['assignments']=RosterAssignment::where('period_id',$period->id)->where('user_id',auth()->id())->get()->keyBy('work_date');return view('nurse.index',$data);}
public function preference(Request $r){abort_unless(auth()->user()->role==='nurse',403);$data=$r->validate(['date'=>'required|date_format:Y-m-d','shift_type_id'=>'required|exists:shift_types,id']);$period=RosterPeriod::where('month',substr($data['date'],0,7).'-01')->firstOrFail();abort_unless($period->status==='open'&&(!$period->deadline||now()->lte($period->deadline)),403);ShiftPreference::updateOrCreate(['user_id'=>auth()->id(),'work_date'=>$data['date']],['period_id'=>$period->id,'shift_type_id'=>$data['shift_type_id']]);return back()->with('ok','تم حفظ الرغبة');}
public function assignment(Request $r){$this->admin();$data=$r->validate(['user_id'=>['required',Rule::exists('users','id')->where('role','nurse')],'date'=>'required|date_format:Y-m-d','shift_type_id'=>'required|exists:shift_types,id']);$period=RosterPeriod::where('month',substr($data['date'],0,7).'-01')->firstOrFail();abort_if($period->status==='published',403);DB::transaction(function()use($data,$period){$a=RosterAssignment::updateOrCreate(['user_id'=>$data['user_id'],'work_date'=>$data['date']],['period_id'=>$period->id,'shift_type_id'=>$data['shift_type_id'],'updated_by'=>auth()->id()]);DB::table('audit_logs')->insert(['actor_id'=>auth()->id(),'action'=>'assignment.saved','entity'=>'roster_assignment','entity_id'=>$a->id,'details'=>json_encode($data),'created_at'=>now(),'updated_at'=>now()]);});return back()->with('ok','تم حفظ الشيفت');}
public function status(Request $r,RosterPeriod $period){$this->admin();$data=$r->validate(['status'=>['required',Rule::in(['open','closed','published'])],'deadline'=>'nullable|date']);$period->update(['status'=>$data['status'],'deadline'=>$data['deadline']??$period->deadline,'published_at'=>$data['status']==='published'?now():null,'published_by'=>$data['status']==='published'?auth()->id():null]);return back()->with('ok','تم تحديث الحالة');}
public function staff(Request $r){$this->admin();$data=$r->validate(['name'=>'required|string|max:255','employee_no'=>'required|string|max:80|unique:users,employee_no','staff_code'=>'nullable|string|max:80','email'=>'required|email|unique:users,email','password'=>'required|string|min:12','department_id'=>'nullable|exists:departments,id']);User::create([...$data,'role'=>'nurse','is_active'=>true,'password'=>Hash::make($data['password'])]);return back()->with('ok','تمت الإضافة');}
public function activate(Request $r,User $user){$this->admin();abort_unless($user->role==='nurse',403);$data=$r->validate(['email'=>'required|email|unique:users,email,'.$user->id,'password'=>'required|string|min:12']);$user->update(['email'=>$data['email'],'password'=>Hash::make($data['password']),'is_active'=>true]);return back()->with('ok','تم التفعيل');}
public function export(Request $r){$this->admin();$period=$this->period($r);$users=User::where('role','nurse')->orderBy('name')->get();$assignments=RosterAssignment::where('period_id',$period->id)->with('shiftType')->get()->keyBy(fn($a)=>$a->user_id.'|'.$a->work_date);$month=Carbon::parse($period->month);return response()->streamDownload(function()use($users,$assignments,$month){$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,array_merge(['رقم الموظف','اسم الممرض','الكود'],range(1,$month->daysInMonth)));foreach($users as $u){$row=[$u->employee_no,$u->name,$u->staff_code];foreach(range(1,$month->daysInMonth) as $day){$date=$month->copy()->day($day)->toDateString();$row[]=$assignments->get($u->id.'|'.$date)?->shiftType?->code??'';}fputcsv($f,$row);}fclose($f);},'roster-'.$month->format('Y-m').'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
}
